const p = $('One Item Per Platform').item.json;
const li = $('Post to LinkedIn').item.json || {};
const id = li.urn || li.id || '';
const err = li.error ? (li.error.message || JSON.stringify(li.error)) : '';
return { json: { post_id: p.post_id, platform: 'linkedin', id: err ? '' : id, url: String(id).startsWith('urn:') ? 'https://www.linkedin.com/feed/update/' + id : '', error: err || (id ? '' : 'No post id returned') } };

// Posts one item to the Facebook Page: a photo, a carousel (several photos in one post) or a video.
const p = $('One Item Per Platform').item.json;
const t = $('Get Page Token (FB)').item.json || {};
const page = t.data ? t.data[0] : t;
const done = (id, url, error) => ({ json: { post_id: p.post_id, platform: 'facebook', id: error ? '' : id || '', url: error ? '' : url || '', error: error || (id ? '' : 'No post id returned') } });
if (t.error || !page || !page.access_token) return done('', '', 'Page token: ' + ((t.error && t.error.message) || 'no page found'));
const G = 'https://graph.facebook.com/v26.0/';
const post = async (path, fields) => {
  const r = await this.helpers.httpRequest({ method: 'POST', url: G + path, body: new URLSearchParams({ ...fields, access_token: page.access_token }).toString(), headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, json: true, ignoreHttpStatusErrors: true });
  const j = typeof r === 'string' ? JSON.parse(r) : r || {};
  if (j.error) throw new Error(j.error.error_user_msg || j.error.message || JSON.stringify(j.error));
  return j;
};
try {
  if (p.kind === 'video' && p.video_url) {
    const r = await post(page.id + '/videos', { file_url: p.video_url, description: p.caption });
    return done(r.id, 'https://www.facebook.com/' + page.id + '/videos/' + r.id);
  }
  if (p.kind === 'carousel' && (p.media_urls || []).length > 1) {
    const ids = [];
    for (const url of p.media_urls) ids.push((await post(page.id + '/photos', { url, published: 'false' })).id);
    const fields = { message: p.caption };
    ids.forEach((id, i) => (fields['attached_media[' + i + ']'] = JSON.stringify({ media_fbid: id })));
    const r = await post(page.id + '/feed', fields);
    return done(r.id, 'https://www.facebook.com/' + r.id);
  }
  const r = await post(page.id + '/photos', { url: p.image_url, message: p.caption, alt_text_custom: p.alt_text || '' });
  const id = r.post_id || r.id;
  return done(id, 'https://www.facebook.com/' + id);
} catch (e) {
  return done('', '', e.message || String(e));
}

// Posts one item to Instagram: a photo, a carousel or a Reel. Waits until Instagram has processed it.
const p = $('One Item Per Platform').item.json;
const t = $('Get Page Token (IG)').item.json || {};
const page = t.data ? t.data[0] : t;
const done = (id, url, error) => ({ json: { post_id: p.post_id, platform: 'instagram', id: error ? '' : id || '', url: error ? '' : url || '', error: error || (id ? '' : 'No media id returned') } });
if (t.error || !page || !page.access_token) return done('', '', 'Page token: ' + ((t.error && t.error.message) || 'no page found'));
const ig = p.ig_user_id || (page.instagram_business_account || {}).id;
if (!ig) return done('', '', 'No Instagram account linked to this Facebook Page');
const G = 'https://graph.facebook.com/v26.0/';
const token = page.access_token;
const call = async (method, path, fields) => {
  const qs = new URLSearchParams({ ...fields, access_token: token }).toString();
  const r = await this.helpers.httpRequest(method === 'GET' ? { method, url: G + path + '?' + qs, json: true, ignoreHttpStatusErrors: true } : { method, url: G + path, body: qs, headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, json: true, ignoreHttpStatusErrors: true });
  const j = typeof r === 'string' ? JSON.parse(r) : r || {};
  if (j.error) throw new Error(j.error.error_user_msg || j.error.message || JSON.stringify(j.error));
  return j;
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// Containers must be FINISHED before they can be published (videos take a while).
const ready = async (id, maxSeconds) => {
  for (let waited = 0; waited <= maxSeconds; waited += 5) {
    const s = await call('GET', id, { fields: 'status_code,status' });
    if (s.status_code === 'FINISHED') return;
    if (s.status_code === 'ERROR' || s.status_code === 'EXPIRED') throw new Error('Instagram could not process it: ' + (s.status || s.status_code));
    await sleep(5000);
  }
  throw new Error('Instagram is still processing it, it will be retried');
};
try {
  let container;
  if (p.kind === 'video' && p.video_url) {
    container = (await call('POST', ig + '/media', { media_type: 'REELS', video_url: p.video_url, caption: p.caption, share_to_feed: 'true' })).id;
    await ready(container, 300);
  } else if (p.kind === 'carousel' && (p.media_urls || []).length > 1) {
    const kids = [];
    for (const url of p.media_urls.slice(0, 10)) kids.push((await call('POST', ig + '/media', { image_url: url, is_carousel_item: 'true' })).id);
    for (const k of kids) await ready(k, 60);
    container = (await call('POST', ig + '/media', { media_type: 'CAROUSEL', children: kids.join(','), caption: p.caption })).id;
    await ready(container, 60);
  } else {
    container = (await call('POST', ig + '/media', { image_url: p.image_url, caption: p.caption, alt_text: p.alt_text || '' })).id;
    await ready(container, 60);
  }
  const pub = await call('POST', ig + '/media_publish', { creation_id: container });
  let url = '';
  try { url = (await call('GET', pub.id, { fields: 'permalink' })).permalink || ''; } catch (e) {}
  return done(pub.id, url);
} catch (e) {
  return done('', '', e.message || String(e));
}
